"""Execute native circle and hypercube walks at the original sizes."""

from dataclasses import dataclass

import torch

import flagquantum as fq
from examples.synthesis.tutorials.advanced_tutorials.discrete_quantum_walk.comparisons.circuit import (
    reference_circuit as circle_reference,
)
from examples.synthesis.tutorials.advanced_tutorials.discrete_quantum_walk.quantum_walk_circle.main import (
    main as circle,
)
from examples.synthesis.tutorials.advanced_tutorials.discrete_quantum_walk.quantum_walk_circle_balanced_coin.main import (
    main as balanced_circle,
)
from examples.synthesis.tutorials.advanced_tutorials.discrete_quantum_walk.quantum_walk_hypercube.comparisons.circuit import (
    reference_circuit as cube_reference,
)
from examples.synthesis.tutorials.advanced_tutorials.discrete_quantum_walk.quantum_walk_hypercube.main import (
    build_program as cube,
)
from flagquantum import synth
from flagquantum.compiler.resource_estimation import ResourceEstimate

CIRCLE_SIZE = 128
CIRCLE_STEPS = 50
CUBE_DIMENSION = 4
CUBE_STEPS = 4
SHOTS = 10_000
SEED = 198


@dataclass(frozen=True)
class Observation:
    positions: tuple[int, ...]
    counts: tuple[int, ...]
    exact: tuple[float, ...]
    maximum_error: float
    work_probability: float
    resources: ResourceEstimate

    def observed(self, position: int) -> float:
        return self.counts[self.positions.index(position)] / SHOTS


@dataclass(frozen=True)
class Walks:
    circle: Observation
    balanced: Observation
    cube: Observation
    classical_circle: tuple[int, ...]
    classical_cube: tuple[int, ...]


def observe(
    program: synth.Program, reference: fq.Circuit, *, signed: bool, seed: int
) -> Observation:
    result = fq.run(program)
    expected = fq.run(reference).statevector().flatten()
    actual = result.statevector().reshape(expected.numel(), -1)
    error = float((actual[:, 0] - expected).abs().max())
    work = float(actual[:, 1:].abs().square().sum())
    if error >= 1e-11 or work >= 1e-24:
        raise AssertionError(
            f"Walk reference error {error}, workspace probability {work}"
        )
    raw = dict(program.probabilities(result, registers=("x",)))
    size = CIRCLE_SIZE if signed else 1 << CUBE_DIMENSION
    exact = torch.tensor(
        [raw.get((word,), 0.0) for word in range(size)], dtype=torch.float64
    )
    draws = torch.multinomial(
        exact,
        SHOTS,
        replacement=True,
        generator=torch.Generator().manual_seed(seed),
    )
    counts = torch.bincount(draws, minlength=size)
    if signed:
        exact = exact.roll(size // 2)
        counts = counts.roll(size // 2)
    positions = range(-size // 2, size // 2) if signed else range(size)
    resources = program.report["resources"]
    if not isinstance(resources, ResourceEstimate):
        raise TypeError("Expected a measured circuit resource report")
    return Observation(
        tuple(positions),
        tuple(int(value) for value in counts),
        tuple(float(value) for value in exact),
        error,
        work,
        resources,
    )


def circle_walk(*, balanced: bool) -> Observation:
    program = synth.synthesize(
        balanced_circle if balanced else circle,
        classical_inputs={"t": CIRCLE_STEPS},
        max_qubits=8,
        max_workspace=0,
        max_operations=20_000,
        memory_limit_bytes=16 * 1024**2,
    )
    reference = circle_reference(width=7, steps=CIRCLE_STEPS, balanced=balanced)
    return observe(program, reference, signed=True, seed=SEED + int(balanced))


def cube_walk() -> Observation:
    return observe(
        cube(CUBE_STEPS),
        cube_reference(CUBE_STEPS),
        signed=False,
        seed=SEED + 2,
    )


def classical_circle() -> tuple[int, ...]:
    """Start each of the 10,000 classical circle trials from zero."""
    rng = torch.Generator().manual_seed(SEED + 3)
    flips = torch.randint(0, 2, (SHOTS, CIRCLE_STEPS), generator=rng)
    positions = (1 - 2 * flips).sum(dim=1) % CIRCLE_SIZE
    decoded = torch.bincount(positions, minlength=CIRCLE_SIZE).roll(CIRCLE_SIZE // 2)
    return tuple(int(value) for value in decoded)


def classical_cube() -> tuple[int, ...]:
    """Retain the source's single trajectory and visit count at every move."""
    rng = torch.Generator().manual_seed(SEED + 4)
    position = 0
    visits = [0] * (1 << CUBE_DIMENSION)
    for direction in torch.randint(0, CUBE_DIMENSION, (SHOTS,), generator=rng):
        position ^= 1 << int(direction)
        visits[position] += 1
    return tuple(visits)


def run() -> Walks:
    return Walks(
        circle_walk(balanced=False),
        circle_walk(balanced=True),
        cube_walk(),
        classical_circle(),
        classical_cube(),
    )

"""A uniform coin selects a Hamming-distance-one move on a hypercube."""

from typing import Annotated

import flagquantum as fq
from flagquantum import synth
from flagquantum.synth import (
    Output,
    QArray,
    QBit,
    QNum,
    allocate,
    inplace_prepare_amplitudes,
    qfunc,
)

from .operations import diffuse, move
from .physics import COIN_AMPLITUDES, POSITION_AMPLITUDES


@qfunc
def main(
    t: int,
    position_amplitudes: list[float],
    coin_amplitudes: list[float],
    x: Output[QArray[QBit]],
    coin: Output[Annotated[QNum, 2]],
) -> None:
    allocate(4, x)
    allocate(coin)
    inplace_prepare_amplitudes(position_amplitudes, 0, x)
    inplace_prepare_amplitudes(coin_amplitudes, 0, coin)
    for step in range(t):
        diffuse(coin)
        for direction in range(4):
            move(direction, coin, x)


def build_program(
    t: int = 2,
    position_amplitudes: tuple[float, ...] = POSITION_AMPLITUDES,
    coin_amplitudes: tuple[float, ...] = COIN_AMPLITUDES,
) -> synth.Program:
    if type(t) is not int or not 0 <= t <= 16:
        raise ValueError("Use an integer step count in 0..16")
    if len(position_amplitudes) != 16 or len(coin_amplitudes) != 4:
        raise ValueError("Use sixteen position and four coin amplitudes")
    return synth.synthesize(
        main,
        classical_inputs={
            "t": t,
            "position_amplitudes": list(position_amplitudes),
            "coin_amplitudes": list(coin_amplitudes),
        },
    )


if __name__ == "__main__":
    program = build_program()
    result = fq.run(program)
    print(dict(program.probabilities(result, registers=("x", "coin"))))
    print(program.report["resources"])

"""Independent modular permutations; no Fourier gates or synthesis arithmetic."""

import torch

import flagquantum as fq
from examples.synthesis.compare_states import compare_states
from examples.synthesis.tutorials.advanced_tutorials.discrete_quantum_walk.main import (
    build_program,
)


def reference_circuit(
    width: int = 10,
    steps: int = 1,
    balanced: bool = False,
    position: int = 0,
    coherent: bool = False,
) -> fq.Circuit:
    """Use exact basis permutations at small width and a closed one-step state."""
    circuit = fq.Circuit(width + 1, dtype=torch.complex128)
    if width > 7:
        if (steps, balanced, position, coherent) != (1, False, 0, False):
            raise ValueError("wide reference only admits the original one-step state")
        # Starting from zero: (|+1,0> + |-1,1>)/sqrt(2).
        circuit.h(width).x(width - 1)
        for wire in range(width - 1):
            circuit.cx(width, wire)
        return circuit
    for wire in range(width):
        if position & (1 << (width - 1 - wire)):
            circuit.x(wire)
    if coherent:
        for wire in range(width):
            circuit.h(wire)
        circuit.h(width).s(width)
    if balanced:
        circuit.h(width).s(width)
    size = 1 << width
    shift = torch.zeros((2 * size, 2 * size), dtype=torch.complex128)
    for x in range(size):
        for coin in range(2):
            y = (x + (1 if coin == 0 else -1)) % size
            shift[2 * y + coin, 2 * x + coin] = 1
    for _ in range(steps):
        circuit.h(width).any(*range(width + 1), matrix=shift)
    return circuit


def run_example() -> None:
    compare_states(build_program(), reference_circuit(), ("x", "coin"))


if __name__ == "__main__":
    run_example()

"""Synthesize native arithmetic and explicit cascade candidates for CX comparison."""

from dataclasses import dataclass
from typing import Annotated, Literal

import flagquantum as fq
from examples.synthesis.tutorials.advanced_tutorials.discrete_quantum_walk.comparisons.circuit import (
    reference_circuit as circle_reference,
)
from examples.synthesis.tutorials.technology_demonstrations.classiq_paper.quantum_walk.classiq_discrete_quantum_walk.overview.exact_basis import (
    exact_rules,
)
from flagquantum import synth
from flagquantum.compiler import estimate_resources
from flagquantum.compiler.basis_conversion import convert_basis
from flagquantum.compiler.resource_estimation import ResourceEstimate
from flagquantum.core.ir import CircuitIR
from flagquantum.synth import (
    H,
    Output,
    QBit,
    QNum,
    X,
    adjoint,
    allocate,
    control,
    qfunc,
)


@qfunc
def increment(x: QNum) -> None:
    x += 1


@qfunc
def decrement(x: QNum) -> None:
    x -= 1


@qfunc
def cascade(x: QNum) -> None:
    for order in range(9):
        # The compiler expands each callback in its current static loop binding.
        control(x[: 9 - order], lambda: X(x[9 - order]))  # noqa: B023
    X(x[0])


@qfunc
def inverse_cascade(x: QNum) -> None:
    with adjoint():
        cascade(x)


@qfunc
def arithmetic_root(x: Output[Annotated[QNum, 10]], coin: Output[QBit]) -> None:
    allocate(x)
    allocate(coin)
    H(coin)
    control(coin == 0, lambda: increment(x))
    control(coin == 1, lambda: decrement(x))


@qfunc
def cascade_root(x: Output[Annotated[QNum, 10]], coin: Output[QBit]) -> None:
    allocate(x)
    allocate(coin)
    H(coin)
    control(coin == 0, lambda: cascade(x))
    control(coin == 1, lambda: inverse_cascade(x))


@dataclass(frozen=True)
class Candidate:
    objective: Literal["width", "depth"]
    resources: ResourceEstimate
    circuit: CircuitIR


@dataclass(frozen=True)
class Point:
    width_limit: int
    arithmetic: Candidate
    cascade: Candidate


def cost(candidate: Candidate) -> tuple[int, int, int, str]:
    resources = candidate.resources
    return (
        resources.operation_counts.get("cx", 0),
        resources.depth,
        resources.n_qubits,
        candidate.objective,
    )


def select(
    style: Literal["arithmetic", "cascade"],
    width: int,
    conversions: dict[str, tuple[CircuitIR, ResourceEstimate]],
) -> Candidate:
    """Select the fewest actual CX gates among both requested compiler objectives."""
    if not 12 <= width <= 20:
        raise ValueError("The source sweep admits physical widths 12 through 20")
    root = arithmetic_root if style == "arithmetic" else cascade_root
    candidates = []
    objectives: tuple[Literal["width", "depth"], ...] = ("width", "depth")
    for objective in objectives:
        program = synth.synthesize(
            root,
            max_qubits=width,
            max_workspace=width - 11,
            objective=objective,
            max_operations=100_000,
            memory_limit_bytes=64 * 1024**2,
        )
        key = program.circuit.content_hash
        if key not in conversions:
            target = convert_basis(
                program.circuit,
                gates=("cx", "u3"),
                rules=exact_rules(),
                max_added_operations=100_000,
            ).program
            resources = estimate_resources(target)
            if set(resources.operation_counts) - {"cx", "u3"}:
                raise AssertionError("Converted walk escaped the named CX/U3 basis")
            conversions[key] = (target, resources)
        circuit, measure = conversions[key]
        if measure.n_qubits > width:
            raise AssertionError("The converted walk exceeded its physical width")
        candidates.append(Candidate(objective, measure, circuit))
    return min(candidates, key=cost)


def sweep() -> tuple[Point, ...]:
    conversions: dict[str, tuple[CircuitIR, ResourceEstimate]] = {}
    rows: list[Point] = []
    for width in range(12, 21):
        arithmetic = select("arithmetic", width, conversions)
        cascade = select("cascade", width, conversions)
        if rows:
            arithmetic = min(arithmetic, rows[-1].arithmetic, key=cost)
            cascade = min(cascade, rows[-1].cascade, key=cost)
        rows.append(Point(width, arithmetic, cascade))
    return tuple(rows)


def validate(candidate: Candidate) -> float:
    """Compare every physical amplitude for the original one-step input."""
    reference = fq.run(circle_reference(width=10, steps=1)).statevector().flatten()
    actual = fq.run(candidate.circuit).statevector().reshape(reference.numel(), -1)
    error = float((actual[:, 0] - reference).abs().max())
    work = float(actual[:, 1:].abs().square().sum())
    if error >= 1e-10 or work >= 1e-20:
        raise AssertionError(
            f"One-step sweep reference error {error}, workspace probability {work}"
        )
    return error

